'use client';

import { RiMoonLine, RiSunLine } from '@remixicon/react';
import { useAppearance } from '@/hooks/use-appearance';

export function ThemeSwitch({ className = '' }: { className?: string }) {
  const { theme, setTheme } = useAppearance();
  return <div className={`ui-theme-switch ${className}`} role="group" aria-label="Appearance">
    <button type="button" aria-label="Light appearance" aria-pressed={theme === 'light'} onClick={event => setTheme('light', event)}><RiSunLine size={17}/></button>
    <button type="button" aria-label="Dark appearance" aria-pressed={theme === 'dark'} onClick={event => setTheme('dark', event)}><RiMoonLine size={17}/></button>
  </div>;
}

'use client';

import { useLayoutEffect } from 'react';
import { isAccent } from '@/config/appearance';

export function AppearanceInitializer() {
  useLayoutEffect(() => {
    function applyStoredAppearance() {
      try {
        document.documentElement.classList.toggle('dark', localStorage.getItem('appui:theme') === 'dark');
        const accent = localStorage.getItem('appui:accent');
        if (isAccent(accent) && accent !== 'blue') document.documentElement.dataset.accent = accent;
        else delete document.documentElement.dataset.accent;
      } catch { /* Storage may be unavailable in private browsing. */ }
    }
    function onStorage(event: StorageEvent) {
      if (event.key === null || event.key === 'appui:theme' || event.key === 'appui:accent') applyStoredAppearance();
    }
    applyStoredAppearance();
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);

  return null;
}

import colors from './colors.json';

export type Accent = keyof typeof colors.accents;
export const accentNames = Object.keys(colors.accents) as Accent[];
export const accentPalettes = colors.accents;
export const accents = accentNames.map(id => ({ id, label: colors.accents[id].label, swatch: colors.accents[id].ramp['500'] }));

export function isAccent(value: string | null | undefined): value is Accent {
  return value != null && Object.hasOwn(colors.accents, value);
}

'use client';

import { useEffect, useState } from 'react';
import { transitionTheme, type ThemeChangeEvent } from '@/utils/theme-transition';
import { isAccent, type Accent } from '@/config/appearance';

export type Theme = 'light' | 'dark';
export type { Accent } from '@/config/appearance';

export function useAppearance() {
  const [theme, setThemeState] = useState<Theme>('light');
  const [accent, setAccentState] = useState<Accent>('blue');

  useEffect(() => {
    function syncAppearance() {
      setThemeState(document.documentElement.classList.contains('dark') ? 'dark' : 'light');
      const current = document.documentElement.dataset.accent;
      setAccentState(isAccent(current) ? current : 'blue');
    }
    syncAppearance();
    const observer = new MutationObserver(syncAppearance);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class', 'data-accent'] });
    return () => observer.disconnect();
  }, []);

  function setTheme(next: Theme, event?: ThemeChangeEvent) {
    if (document.documentElement.classList.contains('dark') === (next === 'dark')) return;
    void transitionTheme(() => {
      document.documentElement.classList.toggle('dark', next === 'dark');
      try { window.localStorage.setItem('appui:theme', next); } catch { /* Appearance also works without storage. */ }
      setThemeState(next);
    }, event);
  }

  function setAccent(next: Accent) {
    if (next === 'blue') delete document.documentElement.dataset.accent;
    else document.documentElement.dataset.accent = next;
    try { window.localStorage.setItem('appui:accent', next); } catch { /* Appearance also works without storage. */ }
    setAccentState(next);
  }

  return { theme, accent, setTheme, setAccent };
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});

'use client';

import type { MouseEvent } from 'react';
import { flushSync } from 'react-dom';

export type ThemeChangeEvent = Pick<MouseEvent<HTMLElement>, 'clientX' | 'clientY' | 'currentTarget'>;
let transitioning = false;

/** Reveal the new appearance from the pointer, or the control center for keyboards. */
export async function transitionTheme(update: () => void, event?: ThemeChangeEvent) {
  if (transitioning) return;
  if (!document.startViewTransition || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    update();
    return;
  }

  const bounds = event?.currentTarget.getBoundingClientRect();
  const pointer = event && (event.clientX !== 0 || event.clientY !== 0);
  const x = Math.max(0, Math.min(window.innerWidth, pointer ? event.clientX : bounds ? bounds.left + bounds.width / 2 : window.innerWidth / 2));
  const y = Math.max(0, Math.min(window.innerHeight, pointer ? event.clientY : bounds ? bounds.top + bounds.height / 2 : window.innerHeight / 2));
  const diameter = 2.5 * Math.hypot(Math.max(x, window.innerWidth - x), Math.max(y, window.innerHeight - y));
  const root = document.documentElement;
  const mask = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><filter id="soft" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="2"/></filter></defs><circle cx="50" cy="50" r="42" fill="white" filter="url(#soft)"/></svg>';
  const properties = {
    '--theme-reveal-x': `${x}px`,
    '--theme-reveal-y': `${y}px`,
    '--theme-reveal-left': `${x - diameter / 2}px`,
    '--theme-reveal-top': `${y - diameter / 2}px`,
    '--theme-reveal-size': `${diameter}px`,
    '--theme-reveal-mask': `url("data:image/svg+xml,${encodeURIComponent(mask)}")`,
  };
  transitioning = true;
  Object.entries(properties).forEach(([key, value]) => root.style.setProperty(key, value));
  root.classList.add('ui-theme-transitioning');
  let committed = false;
  const commit = () => {
    if (committed) return;
    committed = true;
    flushSync(update);
  };
  try {
    const transition = document.startViewTransition(commit);
    await transition.ready;
    await transition.finished;
  } catch {
    // A hidden tab or interrupted snapshot still needs the requested appearance.
    commit();
  } finally {
    root.classList.remove('ui-theme-transitioning');
    Object.keys(properties).forEach(key => root.style.removeProperty(key));
    transitioning = false;
  }
}
